const fs=require('node:fs'),path=require('node:path');const {publish}=require('../../../lib/reporting');const {ghAdapter}=require('../../../lib/github-api');function input(n){return process.env[`INPUT_${n.toUpperCase().replaceAll('-','_')}`]}function out(k,v){fs.appendFileSync(process.env.GITHUB_OUTPUT,`${k}=${v}\n`)}(async()=>{const d=path.resolve(input('outcome-dir')),identity=JSON.parse(fs.readFileSync(path.join(d,'identity.json'))),outcome=JSON.parse(fs.readFileSync(path.join(d,'outcome.json'))),event=JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH)),gh=ghAdapter({token:input('token'),repo:process.env.GITHUB_REPOSITORY,issueNumber:event.issue.number});const adapters={postStatus:gh.postStatus,postComment:gh.postComment,backoff:async n=>new Promise(r=>setTimeout(r,Math.min(2000,250*n)))};let spec;if(outcome.status==='BLOCKED'&&outcome.reason_code==='CHECKOUT_SHA_MISMATCH'){spec={kind:'refusal',identity,outcome}}else{spec={kind:'canonical',identity,result:JSON.parse(fs.readFileSync(path.join(d,'result.json')))}}const r=await publish(spec,adapters);out('execution-status',outcome.status);out('status-posted',String(r.statusPosted));out('comment-posted',String(r.commentPosted));fs.writeFileSync(path.join(d,'report-state.json'),JSON.stringify(r))})().catch(e=>{console.error(e);process.exitCode=1});
